window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-09"]={"block":"med:med-cirurgia-med-cir-09","label":"MED · MED CIR 09","count":90,"questions":[{"id":"med-cirurgia-med-cir-09-345516","number":"345516","sourceNumber":"345516","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Qual é o parâmetro mais importante na avaliação pré-operatória da reserva funcional\nhepática?","options":{"A":"Tempo de protrombina.","B":"Tempo parcial de tromboplastina.","C":"Albuminemia.","D":"Bilirrubinemia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-183213","number":"183213","sourceNumber":"183213","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em relação à cirurgia laparoscópica, assinale a alternativa INCORRETA.","options":{"A":"A insuflação de CO2 na cavidade abdominal , ao se realizar o pneumoperitônio, resulta em\naumento dos níveis de CO2 na corrente sanguínea.","B":"O pneurmoperitônio pode comprimir os vasos renais, porém, sem alterar o fluxo arterial renal ou\no débito urinário.","C":"Cirurgias laparoscópicas prolongadas e pressão abdominal acima de 15mmHg podem elevar a\nPaCO2.","D":"O retorno venoso aumenta, inicialmente, ao se fazer o pneumoperitônio por compressão sobre a\nveia cava, mas diminui progressivamente com a manutenção da pressão abdominal entre 12mmHg\ne 15mmHg.","E":"Longos períodos de aumento da pressão abdominal, estiramento do peritônio e difusão do CO2\npara o intestino podem causar náuseas e vômitos no pós-operatório."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-280429","number":"280429","sourceNumber":"280429","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Mulher de 32 anos, vítima de ferimento por arma de fogo com orifício de entrada em\nregião lombar direita e saída em região de hipocôndrio direito. Foi decidido pelo cirurgião realizar\numa videolaparoscopia. A contraindicação para este procedimento é:","options":{"A":"Hematúria.","B":"Presença de cirurgias prévias.","C":"Instabilidade hemodinâmica.","D":"Obesidade."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-249416","number":"249416","sourceNumber":"249416","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Durante o procedimento de colecistectomia videolaparoscópica, após realizar o\ndescolamento da vesícula do leito hepático, o anestesista relata que a paciente apresenta\ntaquicardia de 140 batimentos por minutos, associada à hipotensão súbita (70 x 40 mmHg). A\nconduta ideal neste momento é:","options":{"A":"administrar beta-bloqueador endovenoso.","B":"suspender a insuflação do pneumoperitônio.","C":"utilizar vasopressores como noradrenalina.","D":"realizar manobra de Pringle."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-215529","number":"215529","sourceNumber":"215529","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"São esforços para diminuir o sangramento no pós-operatório de cirurgia cardíaca em\npediatria todos os abaixo, EXCETO:","options":{"A":"Uso de antifibrinolíticos.","B":"Transfusão de hemocomponentes.","C":"Reversão adequada da anticoagulação da circulação extracorpórea.","D":"Hiper-hidratação e manter drenos mais elevados."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-201762","number":"201762","sourceNumber":"201762","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Vantagem da laparoscopia sobre a laparotomia:","options":{"A":"Recuperação mais rápida e retorno precoce às atividades.","B":"Melhor visibilidade quando há distensão abdominal.","C":"Menor risco de hipercapnia.","D":"Melhor palpação das estruturas abdominais.","E":"Todas estão corretas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-215484","number":"215484","sourceNumber":"215484","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"São contraindicações absolutas para raquianestesia, EXCETO:","options":{"A":"Sepse.","B":"Hipotensão severa.","C":"Cirurgias de longa duração.","D":"Coagulopatias."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-161332","number":"161332","sourceNumber":"161332","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A infecção de pele e de partes moles complicadas envolve tecidos mais profundos, ou\nrequerem intervenção cirúrgica. A infecção na presença de comorbidades médicas, como diabetes\nmellitus, doença renal crônica ou doença arterial periférica também definem infecção complicada.\nSobre isso, assinale a alternativa INCORRETA.","options":{"A":"Na celulite não necrotizante o agente mais frequente é o Streptococcus pyogenes, outros\nagentes incluem Haemophilus influenzae e o pneumococo.","B":"A infecção polimicrobiana suspeita deve ser tratada com cobertura de patógenos Gram positivos,\nGram-negativos entéricos e patógenos anaeróbios.","C":"Características da infecção necrotizantes de partes moles incluem dor desproporcional aos\nachados do exame físico, edema intenso,\nbolhas, equimose, necrose, anestesia cutânea,\nleucocitose, hiponatremia.","D":"Uma opção contra Staphylococcus aureus resistentes à meticilina são as fluorquinolonas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-158802","number":"158802","sourceNumber":"158802","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Qual a contraindicação absoluta à videolaparoscopia?","options":{"A":"Doença cardíaca.","B":"Abdome agudo obstrutivo.","C":"Abdome agudo em gestante.","D":"Ferimento penetrante abdominal.","E":"Diverticulite perfurada com instabilidade hemodinâmica."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-134296","number":"134296","sourceNumber":"134296","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"O pós-operatório imediato de histerectomia abdominal pode transcorrer sem elevações\nsanguíneas de cortisol e catecolaminas, quando a operação for realizada:","options":{"A":"Por via videolaparoscópica.","B":"Em anestesia geral profunda.","C":"Sob bloqueio anestésico peridural.","D":"Na vigência de anti-inflamatórios não esteroides."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-131365","number":"131365","sourceNumber":"131365","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A colocação de drenos abdominais após cirurgias abdominais colorretais eletivas:","options":{"A":"Diminui a ocorrência de infecção da parede abdominal.","B":"Diminui a ocorrência de infecção pélvica.","C":"Diminui a ocorrência de deiscência de anastomoses.","D":"Diminui a mortalidade pós-operatória.","E":"Não mostra vantagens quando comparada à não drenagem."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-110033","number":"110033","sourceNumber":"110033","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Analise as afirmativas abaixo relacionadas ao processo de cicatrização da ferida\noperatória e assinale a alternativa\nCORRETA. I. Na primeira semana pós-lesão é inibida a\nneoformação vascular; II. O colágeno só começa a ser produzido de 4 a 14 dias após a lesão (fase\nproliferativa); III. O aumento da resistência da ferida cirúrgica à ruptura está associado ao\nacúmulo\nde colágeno tipo I, na fase proliferativa da cicatrização. É CORRETO o que se afirma, APENAS, em","options":{"A":"I.","B":"I e II.","C":"III.","D":"I e III."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-109734","number":"109734","sourceNumber":"109734","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"São complicações da Cirurgia Abdominal e que indicam nutrição parenteral:","options":{"A":"disfunção da boca anastomótica ou fístula gastrintestinal.","B":"peritonite difusa grave e abscesso intraperitoneal grave ou íleo paralítico prolongado.","C":"diarreias graves.","D":"todas as alternativas acima."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-86789","number":"86789","sourceNumber":"86789","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Quanto à anestesia, para que se proceda a uma sutura de uma lesão incisa em região\ndistal de um quirodáctilo, e visando minimizar o inchaço local e a consequente deformação da\nlesão, o Médico de Família e Comunidade deveria preferencialmente fazer:","options":{"A":"Uma explanação ao paciente de que nesse\n\ntipo de procedimento não é necessário fazer anestesia pela localização da lesão;","B":"Uma anestesia local infiltrativa;","C":"Uma anestesia tópica com spray anestésico;","D":"Um bloqueio de campo;","E":"Um bloqueio digital."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-158428","number":"158428","sourceNumber":"158428","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Com relação a antibióticoterapia marque a INCORRETA:","options":{"A":"O antibiótico profilático está indicado para prevenção de infecção de sítio cirúrgico, em\ncirurgias\nlimpas, quando a infecção do sítio cirúrgico no pós-operatório aumenta a mortalidade, como nas\nneurocirurgias, cirurgias cardíacas, ortopédicas e vasculares (em que se utilizam próteses), e em\ncirurgias potencialmente contaminadas e infectadas.","B":"Basicamente, recomenda-se uma cefalosporina de primeira geração, como a cefazolina para\npraticamente todos os procedimentos, com exceção das intervenções sobre o íleo terminal, o cólon\ne o reto, em que se recomenda uma colonoscopia de segunda geração com cobertura para\n\nGram-negativo e anaeróbios, como a cefoxitina.","C":"A antibioticoprofilaxia deve ser iniciada na indução anestésica e os níveis séricos devem ser\nmantidos elevados durante o ato cirúrgico, repetindo-se a cada duas horas (cefoxitina) ou quatro\nhoras (cefazolina) conforme a vida média do antibiótico.","D":"Quanto mais prolongada a antibióticoprofilaxia, maior seleção de flora bacteriana resistente,\nmais efeitos colaterais (gastrintestinais e\ncutâneas) e maiores custos.","E":"A antibióticoprofilaxia, a partir de segunda metade do século XX, trouxe uma diminuição\nadicional nos índices de infecção do sitio\ncirúrgico de 10% (ao final do século XIX), para em torno\nde 3%."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-81004","number":"81004","sourceNumber":"81004","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Quais são as células mais importantes durante as fases principais da cicatrização de\nferidas?","options":{"A":"Neutrófilos, plaquetas, fibroblastos e hepatócitos.","B":"Plaquetas, neutrófilos, queratinócitos e neurônios.","C":"Plaquetas, macrófagos, fibroblastos e queratinócitos.","D":"Macrófagos, miofibroblastos, plaquetas e hepatócitos.","E":"Hemácia, macrófagos, plaquetas e histiócito."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-60874","number":"60874","sourceNumber":"60874","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente foi submetido a uma gastrectomia subtotal com vagotomia troncular, devido à\nestenose péptica do piloro. Recebeu alta sem intercorrência. Retornou com 90 dias, referindo que\n20 a 30 minutos após as refeições, principalmente hiperosmolares, apresentava: náuseas, vômitos\nocasionais, eructações, dor adbominal em cólicas, diarreia explosiva que vem associada com\nsintomas cardiovasculares com palpitações, taquicardia, diaforese, desmaios, tonteiras e rubor.\n\nQual a principal hipótese diagnóstica:","options":{"A":"Úlcera duodenal.","B":"Síndrome de Dumping.","C":"Síndrome da alça aferente.","D":"Gastrite de refluxo alcalino.","E":"Estenose na anastomose gastroentérica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-61499","number":"61499","sourceNumber":"61499","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Na avaliação pré-operatória de uma colecistectomia videolaparoscópica eletiva de um\nhomem com 45 anos de idade, em que a\nanamnese e o exame físico não sugerem doença\ncardíaca isquêmica, insuficiência cardíaca, diabetes mellitus, aterosclerose generalizada ou doença\nrenal crônica, sendo este homem capaz de subir dois andares sem sintomas, a conduta\nrecomendada é:","options":{"A":"Liberar o procedimento.","B":"Solicitar teste ergométrico.","C":"Indicar cintilografia miocárdica.","D":"Realizar ecocardiograma transtorácico.","E":"Pedir ecocardiograma sob stress farmacológico."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-61509","number":"61509","sourceNumber":"61509","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"No 2º dia do pós-operatório de cirurgia cardiotorácica, que trascorreu sem\ncomplicações, paciente desenvolve síndrome\nfebril. Considerando o tempo decorrido entre a\ncirurgia e o aparecimento da febre, a hipótese diagnóstica mais provável, dentre as citadas abaixo,\né:","options":{"A":"Trauma cirúrgico.","B":"Infecção esternal.","C":"Atelectasia pós-cirúrgica.","D":"Medicação peroperatória.","E":"Hipertermia maligna pós-anestesia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-49812","number":"49812","sourceNumber":"49812","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um paciente se encontra no sexto dia de pós-operatório de cirurgia abdominal, com\npicos febris. Ao exame da ferida cirúrgica, nota-se discreta tumefação dolorosa em 1/3 inferior.\nEsse quadro é sugestivo de:","options":{"A":"Seroma.","B":"Infecção.","C":"Hematoma.","D":"Eventração.","E":"Evisceração."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-46693","number":"46693","sourceNumber":"46693","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em qualquer caso de interrupção abrupta da infusão venosa das soluções de\nhiperalimentação parenteral (retirada,\n\"arrancamento\", saída acidental do cateter, término da etapa\nsem continuidade da infusão etc.), qual o cuidado imediato a ser tomado?","options":{"A":"Administração imediata de sol. de lipídios para oferta energética.","B":"Administração imediata de insulina simples 10 Unidades endovenosa.","C":"Administração imediata de sol. de aminoácidos a 10%.","D":"Administração de solução de glicose a 10% por veia periférica ou através de cateter da veia\nsubclávia.","E":"Infusão imediata de solução cristaloide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-249722","number":"249722","sourceNumber":"249722","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente, sexo feminino, 45 anos, com historia de colelitíase, foi submetida à\ncolecistectomia sob anestesia geral,\nconvertida para aberta por dificuldades técnicas. Cursa com\ndor moderada e apresenta, no primeiro dia pós-operatório da colecistectomia, episódio de febre. A\nalternativa que contém a etiologia mais provável desta febre é:","options":{"A":"seroma.","B":"atelectasia.","C":"pneumonia.","D":"infecção urinária.","E":"infecção de ferida."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-162475","number":"162475","sourceNumber":"162475","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente chega à Unidade de Saúde da Família apresentando sinais flogísticos (calor,\ndor, rubor, edema), além de um nódulo\neritematoso com sinais de flutuação em região de joelho\ndireito há dois dias. Ao fazer a avaliação, o médico da equipe percebe tratar-se de um abcesso. Em\nrelação à técnica de drenagem que deve ser utilizada, é CORRETO afirmar que:","options":{"A":"Um dreno de Penrose deve ser introduzido no local da incisão com 1 ou 2 cm para fora.","B":"A incisão deve ser pequena com o intuito de possibilitar a drenagem espontânea da secreção\npurulenta do interior do abcesso.","C":"A pele circunjacente deve ser espremida depois da drenagem espontânea, com o objetivo de\nque a secreção acumulada em loculações possa\nse exteriorizar.","D":"Um anestésico como técnica de bloqueio de campo regional deve ser utilizado, com objetivo de\nevitar que o paciente sinta dor durante a realização do procedimento.","E":"O uso de campo estéril, assim como de luvas estéreis, máscara e óculos de proteção não se\nfazem necessários, porque se trata de uma lesão infectada, assim não é necessário que o\nprocedimento seja asséptico."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-139757","number":"139757","sourceNumber":"139757","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre diérese, hemostasia e síntese, indique a alternativa CORRETA.","options":{"A":"São operações necessárias.","B":"São operações eventuais.","C":"São operações fundamentais.","D":"Todas as alternativas estão corretas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-134783","number":"134783","sourceNumber":"134783","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Quanto aos fatores que interferem na cicatrização da ferida operatória:","options":{"A":"Desvitalização tecidual e necrose, presença de corpo estranho, infecção e radioterapia são\nfatores sistêmicos.","B":"Nutrição, proteínas, corticoides e anti-inflamatórios não esteroidais, idade avançada e diabetes\nsão fatores locais.","C":"Desvitalização tecidual e necrose, presença de corpo estranho, infecção e radioterapia são\nfatores locais.","D":"Nutrição, proteínas, corticoides e anti-inflamatórios não esteroidais, idade avançada e diabetes\nsão fatores sistêmicos."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-259689","number":"259689","sourceNumber":"259689","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente, 60 anos, com diagnóstico de lesão duodenal subestenosante, refere hiporexia\ne episódios de vômitos após alimentação, além\nde perda ponderal de 15 kg em 3 meses (peso\nhabitual 65 kg). Foi internado na enfermaria de cirurgia geral para avaliar a possibilidade de\ncirurgia. Realizou tomografia que evidencia nódulos hepáticos bilaterais de aproximadamente 1,5 a\n2 cm e adenomegalias em hilo hepático de pequena curvatura. Exames admissionais: albumina\n2,8g/dl; Hb 10g/dl e leuc 6600/mm³. Em relação ao suporte nutricional, qual deverá ser a melhor\nconduta para esse paciente?","options":{"A":"Iniciar o suporte nutricional por NPT no pré-operatório.","B":"Realizar derivação gastro-jejunal para dieta via oral.","C":"Realizar jejunostomia para suporte nutricional, via enteral.","D":"Passar sonda nasoenteral por endoscopia e manter a dieta enteral."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-126957","number":"126957","sourceNumber":"126957","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente masculino, 35 anos, será submetido à colecistectomia videolaparoscópica sob\nanestesia geral. Nega comorbidades e alergias. Monitorização com oximetria de pulso,\ncardioscopia, capnografia, monitores de dados Biespectrais (BIS) e pressão arterial não invasiva.\n\nMinutos após indução da anestesia, paciente passa a apresentar queda da saturação pelo oxímetro\nde pulso, pressão arterial normal, BIS = 50 e\ncapnografia não mostra curva de CO2. Realizada\nausculta pulmonar bilateral na qual não se verificou murmúrio vesicular. Qual o diagnóstico provável\nda condição anestésica desse paciente?","options":{"A":"Pneumotórax.","B":"Anestesia superficial.","C":"Broncoespasmo grave.","D":"Intubação esofágica não diagnosticada."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-102106","number":"102106","sourceNumber":"102106","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Homem de 60 anos, com história de disfagia progressiva de sólidos para líquidos\nassociada a perda de peso de 10 kg em três\nmeses. Alimenta-se com dificuldade, apenas com\nlíquidos, refere regurgitação ocasional e tosse. Hábitos: tabagismo 30 maços/ano. Ao exame:\nemagrecido (++/4+). TC toracoabdominal mostra estreitamento de esôfago médio de aspecto\nneoplásico com plano de clivagem com vias aéreas com passagem de contraste para o estômago,\nsem adenomegalias detectáveis, pulmões de aspecto normal e demais órgãos sem alterações.\n\nAguarda endoscopia para realizar biópsia. HPP: sem intercorrências clínicas. Qual a melhor via de\nacesso para terapia nutricional para esse\npaciente?","options":{"A":"Dieta por sonda nasogástrica/enteral.","B":"Dieta por gastrostomia.","C":"Dieta por jejunostomia.","D":"Dieta parenteral."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-81265","number":"81265","sourceNumber":"81265","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente masculino, 60 anos, foi vítima de perfuração por arma de fogo em região\nepigástrica, sendo prontamente levado ao\nhospital de trauma mais próximo e submetido à\nlaparotomia exploradora (LE). Evidenciou-se lesão transfixante de duodeno atingindo mais de 50%\nda circunferência intestinal e parede anterior da veia cava. Nesse momento, foi posicionado dreno\nde Blake® na retrocavidade dos epiplons. O paciente foi mantido no pós-operatório na Unidade de\nTerapia Intensiva evoluindo ainda no 7° pós-operatório com um débito diário do dreno de 550 ml\ncompatível com fístula duodenal. Qual a melhor conduta terapêutica para esse caso?","options":{"A":"Iniciar suporte nutricional, imediatamente, por via enteral ou parenteral.","B":"Iniciar tratamento conservador, oferecendo dieta oral pobre em fibras.","C":"Reoperar, imediatamente, e diverticulização duodenal.","D":"Reoperar, imediatamente, para fechamento da fístula."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-65753","number":"65753","sourceNumber":"65753","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um paciente com síndrome de Poland foi diagnosticado com neoplasia gástrica\navançada. Após a indução anestésica, foi\nrealizada a punção de acesso venoso central na veia\nsubclávia esquerda, utilizando a técnica de Seldinger. Durante a realização do inventário da\ncavidade, o paciente passou a apresentar abaulamento da hemicúpula diafragmática esquerda e\ndiminuição da saturação à oximetria de pulso. Diante do exposto, qual o diagnóstico mais provável\ne a conduta mais adequada?","options":{"A":"Provavelmente o paciente se encontra com hemotórax esquerdo, sendo a drenagem de tórax a\nmelhor opção terapêutica.","B":"Provavelmente o paciente se encontra com pneumotórax esquerdo, sendo a drenagem de tórax\na melhor opção terapêutica.","C":"Provavelmente o paciente se encontra com quilotórax esquerdo, sendo a drenagem de tórax ou\na descompressão emergencial com uma agulha calibre\n18 as melhores opções terapêuticas.","D":"Provavelmente o paciente se encontra com hemotórax esquerdo, sendo a descompressão\nemergencial com uma agulha calibre 18 na linha\nmesoclavicular, no segundo espaço intercostal\nanterior, a melhor opção terapêutica.","E":"Provavelmente o paciente se encontra com pneumotórax esquerdo, sendo a descompressão\nemergencial com uma agulha calibre 18 na linha mesoclavicular, no segundo espaço intercostal\nanterior, a melhor opção terapêutica."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-65785","number":"65785","sourceNumber":"65785","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente masculino, 70 anos, com angina instável e obstrução parcial grave das três\nprincipais coronárias, deverá ser submetido à revascularização do miocárdio. É diabético, utilizando\nhipoglicemiantes orais, com glicemia capilar de jejum de 350 mg/dl e Cr de 2,8 mg/dl, em\nacompanhamento irregular na unidade de saúde. Apresenta ainda hipertensão arterial sistêmica e,\nno exame físico atual, PA = 180 x 110. Qual a classificação de estado físico deste paciente (P) de\nacordo com o que preconiza a Sociedade Americana de Anestesiologia?","options":{"A":"P1.","B":"P2.","C":"P3.","D":"P4.","E":"P5."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-65766","number":"65766","sourceNumber":"65766","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente de 60 anos é internado na UTI, no pós-operatório de necrosectomia por\npancreatite necro-hemorrágica. Apresenta estado geral\ngrave, taquicardia, hipotensão responsiva à\nadministração de fármacos vasoativos, fraqueza muscular que impede desmame de ventilador\npulmonar mecânico, náusea, vômitos e febre. As culturas são negativas para crescimento\nbacteriano. Os exames laboratoriais indicam: hipoglicemia, hiponatremia e hipercalemia. Dentre as\nalterações hormonais que ocorrem no período perioperatório de pacientes graves, assinale a\nalternativa que justifica os achados clínicos e laboratoriais descritos no caso acima.","options":{"A":"Insuficiência adrenal.","B":"Resistência à insulina.","C":"Excesso de catecolaminas.","D":"Resistência adquirida ao GH.","E":"Insuficiência de produção de TSH."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-365621","number":"365621","sourceNumber":"365621","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Uma paciente de 55 anos de idade, com histórico de hipertensão arterial controlada\ncom medicamentos, internou-se para uma\ncolecistectomia eletiva em razão de episódios\nrecorrentes de cólica biliar. Durante a avaliação pré-operatória, a paciente relatou ter tomado sua\nmedicação anti-hipertensiva na manhã do dia da cirurgia, porém não conseguiu realizar a consulta\ncom cardiologista para avaliação de risco cirúrgico. Ao exame físico, apresentou PA = 176 mmHg x\n90 mmHg, FC = 80 bpm, FR = 18 irpm e SatO2 = 98% a.a. Com relação a esse caso clínico,\nassinale a alternativa que indica a conduta mais apropriada acerca do preparo pré-operatório e da\nmedicação anti-hipertensiva.","options":{"A":"Prosseguir com a cirurgia conforme agendado, uma vez que a pressão arterial está dentro da\nfaixa aceitável.","B":"Adiar a cirurgia para otimizar o controle da pressão arterial, solicitando monitorização\nambulatorial da pressão arterial (MAPA) e risco cirúrgico.","C":"A paciente não precisará realizar uma avaliação cardiovascular mais detalhada para determinar\nse ela está apta para a cirurgia. Poderá\nprosseguir com a cirurgia sem necessidade de remarcação.","D":"Será necessário administrar medicação anti-hipertensiva adicional para normalizar a pressão\narterial antes da cirurgia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-298848","number":"298848","sourceNumber":"298848","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A profilaxia de TVP está indicada em\ntodo pós-operatório, e as medidas variam de acordo com o risco do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-298849","number":"298849","sourceNumber":"298849","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. No estado de pós-operatório, o paciente\napresenta alterações hormonais referentes à resposta endócrino metabólica e imunológica ao\ntrauma (REMIT). Entre elas, estão a elevação do glucagon, ACTH e cortisol e a redução da\ninsulina, o que torna os pacientes em pós-operatório com controles glicêmicos mais elevados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-214387","number":"214387","sourceNumber":"214387","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Uma paciente de 32 anos de idade, obesa (IMC 38 Kg/m²), diabética tipo II e em uso de\nhipoglicemiante oral, em tratamento de transtorno depressivo maior (bem controlado), comparece\nao consultório médico demonstrando interesse em realizar cirurgia bariátrica para emagrecer, pois\ngostaria de reduzir o peso por questões estéticas. A respeito desse caso clínico e da cirurgia\nbariátrica, e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A paciente\nmencionada não apresenta risco maior de infecção da ferida, formação de hematoma, hérnia\nincisional e complicações clínicas, em relação a outros pacientes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-177553","number":"177553","sourceNumber":"177553","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, IMC 42, submetida a cirurgia bariátrica\ncom técnica aberta há 8 dias, vem à emergência\ncom queixa de dor e saída de secreção purulenta\nfétida na ferida operatória. O exame físico não apresenta outras alterações. Considerando o caso\nclínico apresentado e os conhecimentos médicos relacionados à infecção do sítio cirúrgico, julgue o\nitem a seguir. São alguns fatores de risco relacionados ao paciente: imunossupressão, transfusões\nsanguíneas transoperatórias, idade, neoplasia e esteroides.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-177555","number":"177555","sourceNumber":"177555","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, IMC 42, submetida a cirurgia bariátrica\ncom técnica aberta há 8 dias, vem à emergência\ncom queixa de dor e saída de secreção purulenta\nfétida na ferida operatória. O exame físico não apresenta outras alterações. Considerando o caso\nclínico apresentado e os conhecimentos médicos relacionados à infecção do sítio cirúrgico, julgue o\nitem a seguir. Desnutrição e altos níveis de albumina estão associados ao aumento da infecção no\nsítio cirúrgico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-177556","number":"177556","sourceNumber":"177556","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, IMC 42, submetida a cirurgia bariátrica\ncom técnica aberta há 8 dias, vem à emergência\ncom queixa de dor e saída de secreção purulenta\nfétida na ferida operatória. O exame físico não apresenta outras alterações. Considerando o caso\nclínico apresentado e os conhecimentos médicos relacionados à infecção do sítio cirúrgico, julgue o\nitem a seguir. Feridas cirúrgicas em que o trato digestivo é violado de forma controlada são\nclassificadas como limpas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-177558","number":"177558","sourceNumber":"177558","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente do sexo feminino, 35 anos de idade, IMC 42, submetida a cirurgia bariátrica\ncom técnica aberta há 8 dias, vem à emergência\ncom queixa de dor e saída de secreção purulenta\nfétida na ferida operatória. O exame físico não apresenta outras alterações. Considerando o caso\nclínico apresentado e os conhecimentos médicos relacionados à infecção do sítio cirúrgico, julgue o\nitem a seguir. A preparação do sítio cirúrgico não modifica a incidência de infecção local.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-152070","number":"152070","sourceNumber":"152070","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. A febre pós-operatória é\ncomum na ausência de infecção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-152142","number":"152142","sourceNumber":"152142","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. O processo de resposta\nendocrinometabólica ao trauma no qual o Paciente 3 se encontra, reage ao jejum prolongado com\ncatabolismo, estabelecido por redução na lipólise e aumento da proteólise.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-82049","number":"82049","sourceNumber":"82049","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Acerca dos sistemas cardiovascular, gastrointestinal e endócrino, julgue o item que se\nsegue. Hipertensão arterial e insuficiência renal crônica associadas aumentam consideravelmente o\nrisco de complicações cardiovasculares.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-79648","number":"79648","sourceNumber":"79648","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Para um paciente estável, que realizará uma cirurgia de apendicite aguda, assinale a\nalternativa que apresenta o(s) exame(s) que poderia(m) ser dispensado(s).","options":{"A":"TSH, T3 e T4.","B":"Hb e Ht.","C":"PCR.","D":"Tipagem sanguínea.","E":"Contagem de plaquetas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-64612","number":"64612","sourceNumber":"64612","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em relação a complicações cirúrgicas, assinale a alternativa que apresenta a\ncomplicação respiratória mais frequente no\npós-operatório e que, comumente, é a causa de febre\nnas primeiras 48 horas após o procedimento cirúrgico.","options":{"A":"Pneumotórax.","B":"Embolia Pulmonar.","C":"Derrame Pleural.","D":"Atelectasia.","E":"Pneumonia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-64664","number":"64664","sourceNumber":"64664","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em relação às alterações metabólicas observadas durante uma intervenção cirúrgica,\nassinale a alternativa correta.","options":{"A":"Há aumento dos níveis séricos de interleucinas e queda dos níveis de glucagon.","B":"Há diminuição dos níveis séricos de aldosterona e do Hormônio Antidiurético (ADH).","C":"Há diminuição dos níveis séricos de cortisol, com recrutamento de ácidos graxos pelo fígado.","D":"Há aumento dos níveis séricos de cortisol em resposta ao aumento das concentrações do\nHormômio Adrenocorticotrófico (ACTH).","E":"Há aumento da síntese proteica muscular."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-301283","number":"301283","sourceNumber":"301283","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Uma paciente de 44 anos de idade, com diabetes tipo 2, relata dores abdominais há\ncerca de seis meses, principalmente em\nhipocôndrio direito e flanco direito. Realizou ultrassom de\nabdome, o qual mostrou múltiplos cálculos na vesícula biliar, que se encontrava com paredes finas\ne sem dilatação de vias biliares. Apresentava bilirrubina total de 0,7 mg/dL, AST = 35 UI (normal\naté\n40), ALT = 64 (normal até 40 UI), fosfatase alcalina = 342 UI (normal até 250) e Gama GT = 743 UI\n(normal até 110). Com base nesse caso clínico hipotético, julgue o item. No caso de ser indicada a\ncolecistectomia eletiva, o emprego de antibióticos após a cirurgia deve ser mantido por uma\nsemana, para se evitarem as complicações infecciosas pós-operatórias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-273339","number":"273339","sourceNumber":"273339","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"As cirurgias minimamente invasivas são cada vez mais frequentes, a confecção do\npneumoperitônio, traz as seguintes repercussões fisiológicas:","options":{"A":"Aumento da Resistência Vascular Sistêmica, Aumento da Pressão Arterial Média, Diminuição do\nDébito Cardíaco e Aumento da Pressão Venosa Central.","B":"Diminuição da Resistência Vascular Sistêmica, Diminuição da Pressão Arterial Média, Aumento\ndo Débito Cardíaco e Aumento da Pressão Venosa\nCentral.","C":"Diminuição da Resistência Vascular Sistêmica, Diminuição da Pressão Arterial Média,\nDiminuição do Débito Cardíaco e Diminuição da Pressão Venosa Central.","D":"Aumento da Resistência Vascular Sistêmica, Aumento da Pressão Arterial Média, Aumento do\nDébito Cardíaco e Aumento da Pressão Venosa Central."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-274635","number":"274635","sourceNumber":"274635","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Com o advento das fibras ópticas de iluminação, conjugado com o desenho de\ninstrumentais cirúrgicos que possibilitavam a\nmanipulação dos órgãos internos com menores áreas\nde dissecção, surgiram os primeiros procedimentos videolaparoscópicos. Uma desvantagem da\ncirurgia laparoscópica é:","options":{"A":"O custo do procedimento em termos de equipamentos e manutenção.","B":"O tempo de permanência hospitalar e o retorno às atividades normais.","C":"A quantidade de trauma cirúrgico e a dor pós-operatória.","D":"O efeito estético e a resposta metabólica ao trauma."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-291534","number":"291534","sourceNumber":"291534","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente de 40 anos de idade, sexo feminino, procura unidade pública de pronto\natendimento com queixa de dor em ferida operatória de ressecção de \"nódulo\" de 5 cm de\ndiâmetro, na região escapular direita, há 2 dias. Ao exame, ferida cirúrgica com edema, eritema,\ncalor e dor à palpação, associada a flutuação e exsudação em bordos da sutura. Com base nas\ninformações, qual a conduta propedêutico terapêutica para essa paciente?","options":{"A":"Drenagem por retirada parcial de pontos.","B":"Ultrassonografia de partes moles.","C":"Punção com agulha fina.","D":"Antibioticoterapia oral."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-230588","number":"230588","sourceNumber":"230588","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre os agentes hipnóticos endovenosos utilizados para anestesia, assinale a\nCORRETA:","options":{"A":"o etomidato apresenta estabilidade cardiovascular importante, e reduz a liberação de histamina,\npor isso é indicado em pacientes que apresentam\nbroncoespasmo.","B":"o etomidato é muito utilizado no protocolo de intubação assistida por drogas (sequência rápida),\npois apresenta estabilidade cardiovascular,\nporém aumenta liberação de histamina, o que pode\npiorar quadros de broncoespasmo.","C":"o etomidato é a droga de escolha na manutenção do protocolo de anestesia venosa total, pois\nestimula o eixo adreno-cortical, melhorando a resposta endócrino metabólica ao trauma.","D":"o etomidato é a única droga hipnótica que é contraindicada no protocolo de sequência rápida de\nintubação, pois apresenta bloqueio neuromuscular não despolarizante."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-175088","number":"175088","sourceNumber":"175088","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Somente não podemos afirmar que o Tubo Esofágico Traqueal (Combitube) apresenta\na seguinte característica descrita:","options":{"A":"Quando usamos o Tubo Esofágico Traqueal (Combitube), ao se intubar o esôfago, ocorre um\nisolamento deste e o ar passa pelas fenestrações do tubo, ventilando os pulmões.","B":"Tubo Esofágico Traqueal (Combitube) oferece vantagens similares as da intubação orotraqueal.","C":"Tubo Esofágico Traqueal (Combitube) produz isolamento da via aérea, redução no risco de\naspiração e ventilação segura.","D":"Tubo Esofágico Traqueal (Combitube) trata-se de uma via aérea avançada definitiva."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-80705","number":"80705","sourceNumber":"80705","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Assinale a alternativa que apresenta o sinal mais frequente de transfusão acidental de\nsangue incompatível em um paciente anestesiado.","options":{"A":"Aumento da pressão diastólica arterial.","B":"Sangramento generalizado anormal.","C":"Diminuição abrupta da temperatura corporal.","D":"Calafrios.","E":"Urticária."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-97739","number":"97739","sourceNumber":"97739","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um homem com 23 anos de idade, obeso, encontra-se no terceiro dia pós-operatório\nde laparotomia exploradora e colorrafia direita\napós trauma abdominal perfurante. Apresentou dois\npicos febris com temperatura axilar = 38,5°C. A ausculta pulmonar apresenta diminuição do\nmurmúrio vesicular em bases. O abdome é flácido, com dor à palpação ao redor da incisão e os\nruídos hidroaéreos estão diminuídos em número e intensidade. A radiografia simples de abdome\nmostrou pneumoperitôneo com leve distensão de alças. A ultrassonografia abdominal mostrou\nacúmulo de gases e líquidos nas alças, com pequena coleção de líquido na pelve, cuja análise foi\nprejudicada pelas condições do paciente. Hemograma com leucocitose moderada, sem desvio. O\npaciente fez uso de antibioticoterapia profilática, pois não havia contaminação grosseira da\ncavidade abdominal. Considerando as possíveis causas da febre no pós-operatório, qual deve ser a\nconduta correta para esse paciente?","options":{"A":"Iniciação de antibioticoterapia de amplo espectro.","B":"Conduta expectante; aguardar evolução clínica.","C":"Exploração da ferida abdominal.","D":"Reintervenção cirúrgica."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-75478","number":"75478","sourceNumber":"75478","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Homem com 35 anos de idade, no 3º dia pós-operatório de apendicectomia,\n\nencontra-se internado em enfermaria coletiva de pequeno hospital secundário. O achado cirúrgico\nfoi de uma apendicite aguda em fase\ngangrenosa. Foi iniciada a antibioticoterapia com\nadministração de gentamicina e metronidazol e a alimentação via oral com boa aceitação, após a\neliminação de flatos e fezes. Não apresentou febre. Ao exame, a ferida cirúrgica encontra-se\nhiperemiada, discretamente\n\nabaulada e com saída de material purulento. A conduta para esse caso, além do esclarecimento ao\npaciente, é:","options":{"A":"manter a antibioticoterapia e curativos diários.","B":"trocar antibioticoterapia, aplicar calor local e curativos diários.","C":"manter a antibioticoterapia, retirar os pontos cirúrgicos para drenagem da secreção e curativos\ndiários.","D":"trocar antibiotioterapia, indicar a realização de exame de imagem pelo risco de infecção\nintracavitária.","E":"manter antibiotioterapia, indicar a exploração cirúrgica da ferida operatória pelo risco de\ninfecção\n\nintracavitária."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-352196","number":"352196","sourceNumber":"352196","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Na cirurgia videolaparoscópica o acesso ao abdome e a instalação do pneumoperitônio\nsão os passos iniciais e que albergam\npossíveis complicações. Sobre o tema, podemos afirmar\nque:","options":{"A":"Na técnica fechada é utilizada a agulha de Veress, cujo posicionamento correto pode ser\nidentificado, entre outros métodos, pela detecção de alta pressão pelo insuflador.","B":"A insuflação veloz do gás carbônico pode repercutir com restrição ventilatória e alcalose.","C":"O local de introdução dos trocartes de trabalho deve ser preferencialmente através do músculo\nreto abdominal, local de menor incidência de\nlesões vasculares.","D":"Uma das vantagens da utilização do gás carbônico é o seu alto poder de difusão, o que contribui\npara reduzir a chance de embolia gasosa."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-321156","number":"321156","sourceNumber":"321156","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em uma paciente de alto risco de tromboembolismo venoso, com contraindicação ao\nuso de anticoagulante, é CORRETO afirmar que\na alternativa preferencial deve ser de:","options":{"A":"Meias elásticas.","B":"Filtro de veia cava.","C":"Monitoramento com doppler.","D":"Compressão pneumática intermitente."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-334729","number":"334729","sourceNumber":"334729","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em 1846, Ignaz Semmelweis, médico húngaro, reportou a redução no número de\nmortes maternas por infecção puerperal após a\nimplantação da prática de higienização das mãos\nem um hospital em Viena. Desde então, esse procedimento tem sido recomendado como medida\nprimária no controle da disseminação de agentes infecciosos. Todo médico deve reconhecer a\nimportância destes cuidados, e, evidentemente, praticá-los em suas atividades. Acerca deste tema,\nassinale a afirmativa correta:","options":{"A":"Preparo pré-operatório de mãos ou antissepsia cirúrgica das mãos é uma prática obrigatória\nantes de qualquer cirurgia de médio e grande\nporte, e tem por objetivo eliminar as microbiotas\ntransitória e residente das mãos do cirurgião.","B":"Para o preparo pré-operatório de mãos, a clorexidina é o agente antisséptico mais usado por ter\nefeitos excelentes contra bactérias gram-positivas, gram-negativas, micobactérias e fungos, sendo,\ninclusive, esporicida.","C":"A mais recente atualização da Norma Regulamentadora (NR) 32 permite que profissionais\nutilizem unhas postiças como adornos, desde que\nestejam curtas e limpas, no contato com o\npaciente.","D":"O ceticismo dos profissionais de saúde a respeito da importância da higienização de mãos é um\ndos fatores apontados por eles próprios para\na baixa adesão a esta prática."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-334731","number":"334731","sourceNumber":"334731","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente de 63 anos, operada há 4 dias para tratamento de hérnia inguinal esquerda,\nretornou ao pronto socorro referindo dor\nde média para grande intensidade no membro inferior\nesquerdo, que iniciou naquela madrugada na virilha e progrediu distalmente se tornando mais\nacentuada na panturrilha. Notou aumento do volume da extremidade difusamente, incluindo o pé,\ncom discreto aumento da temperatura e a perna e o pé ficaram mais arroxeados. Ao exame físico\nnão há sinal de Godet positivo. A panturrilha está mais firme que a do lado direito. Tem pulso\npedioso 3+/4. Pressão arterial: 145/95 mmHg, frequência cardíaca: 92 bpm, sem dispneia ou tosse.\nTemperatura axilar: 35.9 graus celsius. De posse desses dados, indique qual medicamento não é\napropriado para o tratamento do caso.","options":{"A":"Varfarina sódica.","B":"Apixabana.","C":"Clopidogrel.","D":"Rivaroxabana."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-321189","number":"321189","sourceNumber":"321189","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre antibióticoprofilaxia nas cirurgias de urgência, correlacione COLUNA I com a\nCOLUNA II. COLUNA I A ? Hérnia\nestrangulada. B ? Hérnia encarcerada. C ? Perfuração intestinal\nrecente. D ? Apendicite aguda necrosada. COLUNA II ( ) 1. Cirurgia limpa. ( ) 2. Cirurgia\npotencialmente contaminada. ( ) 3. Cirurgia contaminada. ( ) 4. Cirurgia infectada. Assinale a\nalternativa que apresenta a sequência CORRETA:","options":{"A":"A2, B3, C2, D4.","B":"A3, B1, C3, D3.","C":"A3, B2, C4, D4.","D":"A2, B1, C4, D3."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-320458","number":"320458","sourceNumber":"320458","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um homem de 50 anos está no 5º pós-operatório de ulcerorrafia gástrica, com patch de\nomento. Refere dor abdominal de forte intensidade e mal-estar geral. Pulso: 120 bpm, PA: 90 × 50\nmmHg, temperatura: 37,2 °C. Ao exame, o abdome apresenta distensão, doloroso a palpação\nprofunda difusamente. Dreno abdominal com saída de 900 mL de líquido bilioso nas últimas 24\nhoras. Conduta mais adequada no momento:","options":{"A":"Nutrição parenteral total e observação clínica rigorosa, sonda nasogástrica e\nantibioticoterapia.","B":"Jejum, sonda nasogástrica aberta e antibioticoterapia. Realizar tomografia para diagnóstico e\ndrenagem de eventuais coleções não contempladas pelo dreno.","C":"Endoscopia para confirmação da provável deiscência da sutura e planejamento cirúrgico.","D":"Exames laboratoriais e tomografia de abdome com contraste oral, para confirmar a suspeita\ndiagnóstica.","E":"Nova abordagem cirúrgica."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-291944","number":"291944","sourceNumber":"291944","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"É considerada CONTRAINDICAÇÃO para abordagem de tratamento por laparoscopia:","options":{"A":"Paciente de 70 anos, com diagnóstico na tomografia de diverticulite com peritonite admitido com\nsinal de Blumberg positivo no andar inferior do abdômen, Glasgow 15, desidratado, PA:\n130X80mmHg e FC: 90bpm.","B":"Paciente vítima de trauma por acidente de motocicleta e lesão do baço admitido após\nressuscitação volêmica pelo SAMU com Glasgow 15,\ndesidratado, PA: 70X40mmHg e FC: 120bpm.","C":"Paciente portador de asma com colecistite aguda, admitido com dados clínicos estáveis e\nsaturação de 94%.","D":"Paciente com apendicite aguda fase 4 admitido com Blumberg positivo em todo abdômen,\nGlasgow 15, desidratado, PA: 110X70 mmHg e FC: 88bpm."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-291642","number":"291642","sourceNumber":"291642","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Assinale a sequência correta em ordem de administração das drogas sedativas durante\no procedimento de intubação orotraqueal:","options":{"A":"Midazolan ? fentanil ? suxametônio.","B":"Propofol ? fentanil ? rocurônio.","C":"Fentanil ? etomidato ? rocurônio.","D":"Etomidato ? fentanil ? rocuronio.","E":"Quetamina ? rocuronio ? fentanil."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-291646","number":"291646","sourceNumber":"291646","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em relação ao preparo pré-operatório de um paciente portador de fibrilação atrial\ncrônica compensada, com ritmo cardíaco irregular,\nem uso de varfarina, diagnosticado com\nadenocarcinoma de cólon esquerdo. Será submetido a colectomia parcial. De acordo com caso\nclínico, qual alternativa constitui a conduta mais adequada:","options":{"A":"Suspender a dose da mediacação cinco dias antes do procedimento, iniciando então heparina\nde baixo peso molecular em dose terapêutica.","B":"Suspender a dose do medicamento 24 horas antes da cirurgia, iniciando heparina de baixo peso\nmolecular em dose profilática.","C":"Substituir a dose da medicação por anticoagulante oral inibidor de fator Xa, sete dias antes da\ncirurgia, sem necessidade de suspensão do inibidor de fator Xa para a cirurgia.","D":"Ajustar a dose do medicamento, para manter a INR abaixo de 1,5 no dia da cirurgia, iniciando\nheparina de baixo peso molecular em dose profilática.","E":"Manter uso de varfarina até 24h antes da cirurgia e prescrever vitamina k antes da cirurgia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-212973","number":"212973","sourceNumber":"212973","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A.L., feminino, 82 anos, cirrose hepática por álcool Child A, deu entrada no\n\npronto-socorro com quadro de dor abdominal de forte intensidade, com início há 3 dias, sobretudo\nem fossa ilíaca direita, associada a vômitos e\nhiporexia. No exame físico estava com taquicardia\n(Fc 110 bpm), PA 70 x 50 mmHg, eupneica em ar ambiente e dor a palpação da FID, com defesa\nlocal. Após ressuscitação com cristaloide, manteve PA inalterada. Em exames laboratoriais,\nleucocitose (leucócitos de 18.500 com 8% de bastões), eletrólitos normais. TC de abdome\nsugestiva de apendicite aguda, com líquido livre na cavidade. Por fim, cirurgião contraindica\nvideolaparoscopia, por qual motivo?","options":{"A":"Extremo de idade: 82 anos.","B":"Apendicite aguda em fase avançada.","C":"Cirrose hepática.","D":"Hipotensão/choque séptico.","E":"Risco da anestesia geral."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-215128","number":"215128","sourceNumber":"215128","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Quando comparado a procedimentos abertos, os procedimentos laparoscópicos\nresultam em:","options":{"A":"Maior supressão imunológica.","B":"Maior produção de hormônios de stress.","C":"Normalização mais lenta dos níveis de citocinas.","D":"Níveis de cortisol sérico maiores.","E":"Não existem diferenças entre os métodos aberto e laparoscópicos em relação às afirmações\nanteriores."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-199579","number":"199579","sourceNumber":"199579","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A infecção de feridas operatórias é quadro corriqueiro nas enfermarias cirúrgicas e sua\nprevenção e tratamento precoce devem ser objetivos constantes de toda a equipe multiprofissional.\nSobre este tema assinale a alternativa CORRETA:","options":{"A":"A antibioticoprofilaxia é usada para prevenir infecção de uma incisão cirúrgica e está\nrecomendada nas cirurgias limpa-contaminadas\n(ou potencialmente contaminadas), contaminadas\ne infectadas.","B":"O tempo de início ideal do antibiótico deve ser dentro de uma hora antes da cirurgia e mantido\naté completar 07 dias da cirurgia.","C":"As primeiras etapas no tratamento de infecção em sítio cirúrgico (ICS) são abertura e o exame\nda porção suspeita da incisão.","D":"As culturas são obrigatórias para o controle de infecção em sítio cirúrgico (ICS) incisionais\nsuperficiais."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-172534","number":"172534","sourceNumber":"172534","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Paciente sexo feminino, hipertensa, diabética, 60 anos, apresenta dispnéia intensa\nsurgida no primeiro dia de pós-operatório de volumosa hérnia incisional. Ao exame clínico\nencontra-se agitada, FR 40rpm, ausculta pulmonar reduzida em bases, padrão respiratório\nsuperficial, SaO2 82% em ar ambiente, ritmo cardíaco regular com FC de 115bpm, PA\n120x80mmHg. Gasometria mostra hipercapnia e hipoxemia. Diante desse caso marque a\nalternativa que melhor expressa a hipótese diagnóstica e condutas subseqüentes:","options":{"A":"Equivalente anginoso, síndrome coronariana aguda. Realizar eletrocardiograma e dosagem de\ntroponina.","B":"Embolia pulmonar. Dosagem de dímero D.","C":"Embolia pulmonar. Angiotomografia de tórax.","D":"Embolia pulmonar ou infarto agudo do miocárdio. Realizar ECG, ecocardiograma e troponina e\ndímero D.","E":"Atelectasias pulmonares. Iniciar ventilação não invasiva e realizar Rx de tórax."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-187443","number":"187443","sourceNumber":"187443","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre laparoscopia, assinale a alternativa CORRETA:","options":{"A":"Na apendicite aguda fase IV é melhor evitar a cirurgia laparoscópica, preferindo a técnica\naberta.","B":"O melhor tratamento para crise de colecistite aguda litiásica é a colecistectomia\nvídeolaparoscópica, com exceção em casos graves\nde necrose de vesícula biliar com perfuração\nde sua parede e coleperitônio.","C":"Está contra-indicada no trauma abdominal fechado.","D":"Todo paciente portador de colelitíase e internado por pancreatite aguda biliar deverá ser\neventualmente submetido a colecistectomia após a resolução do quadro.","E":"Em pacientes diagnosticados com doença péptica ulcerosa perfurada, deve-se evitar o\ntratamento por laparoscopia devido ao difícil\nacesso à lesão e das potenciais aderências causadas\npela doença de base, dificultando uma abordagem laparoscópica eficaz."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-187484","number":"187484","sourceNumber":"187484","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre antibiótico-profilaxia em cirurgia é CORRETO afirmar:","options":{"A":"A dose do antibiótico deve ser repetida a cada 2 horas de procedimento.","B":"O tempo de duração deve ser de no máximo 48h, a depender do porte da cirurgia e do grau de\ncontaminação do procedimento.","C":"Não se encontra indicada em cirurgias limpas.","D":"Pode ser indicada nas cirurgias limpas, potencialmente contaminadas, contaminadas e\ninfectadas.","E":"Deve ser iniciado 10 minutos antes da incisão cirúrgica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-187424","number":"187424","sourceNumber":"187424","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Um paciente desenvolve fístula de alto débito após cirurgia abdominal. O líquido da\nfístula é enviado para avaliação com os seguintes resultados: Na 135, K 5, Cl 70. Qual dos\nseguintes é a fonte mais provável da fístula?","options":{"A":"Estômago.","B":"Intestino delgado.","C":"Pâncreas.","D":"Cólon.","E":"Trato Biliar."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-148565","number":"148565","sourceNumber":"148565","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre a sedação de paciente sob ventilação mecânica invasiva, assinale a assertiva\ncorreta.","options":{"A":"A utilização de bloqueador neuromuscular deve estar condicionada a uma sedação profunda e\nmonitorização adquada do nível de consciência.","B":"Nível de sedação leve a moderado não permite controle da ansiedade, agitação e dor.","C":"O nível de sedação deve ser intenso para permitir melhor tolerância ao ventilador.","D":"Paciente que encontra-se acordado deve ter sua estratégia de sedação interrompida.","E":"Qualquer agente que cause sedação e analgesia pode ser usado."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-149160","number":"149160","sourceNumber":"149160","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"O procedimento adequado em relação à profilaxia antimicrobiana em cirurgias eletivas\nestá indicado na seguinte alternativa:","options":{"A":"Somente os casos de pacientes diabéticos com passado de colecistite aguda deverão utilizar\nantibiótico profilático.","B":"Todas as hernioplastias inguinais merecem profilaxia antibiótica, mesmo as que não usam\nprótese.","C":"Prescrever antibioticoterapia por mais de 48 horas não interfere no aparecimento de microbiota\nresistente e minimiza o risco de infecção de ferida.","D":"É desnecessário o prolongamento da profilaxia antibiótica em cirurgias não complicadas, o que\nevita também o retardo no diagnóstico de infecções instaladas.","E":"Nas colecistectomias, quando ocorrer curtos períodos de contaminação da área cirúrgica, o uso\nde antibiótico profilático não reduz a\nincidência das infecções."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-162548","number":"162548","sourceNumber":"162548","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Associe o período de febre pós-operatória e suas respectivas causas: 1) até 24 horas;\n\n2) até o quinto dia; 3) até o décimo dia; 4) acima do décimo dia; ( ) abscesso Intra-abdominal; ( )\ninfecção da ferida; ( ) infecção urinária; ( ) atelectasia; A sequência correta é:","options":{"A":"2, 1, 3, 4.","B":"4, 3, 2, 1.","C":"2, 1, 4, 3.","D":"3, 4, 2, 1.","E":"4, 2, 3, 1."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-162590","number":"162590","sourceNumber":"162590","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre laparoscopia, assinale a alternativa CORRETA:","options":{"A":"Está contraindicada no trauma abdominal.","B":"O melhor tratamento para crise de colecistite aguda litiásica é a colecistectomia laparoscópica,\ncom exceção em casos graves de necrose de vesícula\nbiliar com perfuração de sua parede e\ncoleperitônio.","C":"O melhor tratamento operatório para apendicite aguda é o laparoscópico, independentemente do\ntempo de evolução da doença.","D":"O paciente portador de pancreatite aguda biliar deverá ser submetido a colecistectomia nas\nprimeiras 48 horas do início do quadro.","E":"A colecistectomia por via laparoscópica é contraindicada em pacientes previamente operados no\nandar supramesocólico."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-162592","number":"162592","sourceNumber":"162592","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre antibiótico-profilaxia em cirurgia é correto afirmar, EXCETO:","options":{"A":"Deve ser iniciado 30 minutos antes da incisão cirúrgica.","B":"O tempo de duração deve ser até de 48h, a depender do porte da cirurgia e do grau de\ncontaminação do procedimento.","C":"Está indicada nas cirurgias potencialmente contaminadas, contaminadas e infectadas","D":"A dose do antibiótico deve ser repetida a cada metade da meia vida da droga.","E":"Não se encontra indicada na maioria das cirurgias limpas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-148533","number":"148533","sourceNumber":"148533","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Identifique o preditor de intubação traqueal difícil sob laringoscopia direta:","options":{"A":"Paciente edêntulo.","B":"Presença de barba espessa.","C":"Protrusão dos dentes incisivos maxiliares.","D":"Síndrome da apneia obstrutiva do sono.","E":"Obesidade moderada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-148572","number":"148572","sourceNumber":"148572","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A prevenção de trombose venosa profunda (TVP) e tromboembolismo pulmonar (TEP)\npermanece um desafio nas áreas cirúrgicas. Assinale a alternativa incorreta quanto à profilaxia de\nTVP e TEP no paciente cirúrgico.","options":{"A":"Pacientes obesos mórbidos têm maior probabilidade de fênomenos tromboembólicos em relação\nà população em geral.","B":"Na ocorrência de plaquetopenia (contagem plaquetária menor que 100.000), o uso de profilaxia\nfarmacológica com heparinas deverá ser suspensa imediatamente.","C":"A associação de deambulação precoce, compressão pneumática intermitente e profilaxia\nfarmacológica, potencializa a prevenção de TVP e TEP.","D":"As operações laparoscópicas têm menos ocorrência de TVP e TEP pela redução de tempo\ncirúrgico e deambulação precoce que proporciona.","E":"Operações de longa duração, com paciente imobilizado à mesa cirúrgica, tem maior chance de\nTVP e TEP necessitando maior atenção em\nações de prevenção."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-131613","number":"131613","sourceNumber":"131613","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Qual camada da parede intestinal tem a maior força tênsil, e consequentemente a\nmaior capacidade de retenção de sutura (característica que deverá ser levada em consideração\ndurante uma anastomose gastrointestinal)?","options":{"A":"Serosa.","B":"Mucosa.","C":"Submucosa.","D":"Muscular.","E":"Muscular da mucosa ."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-127159","number":"127159","sourceNumber":"127159","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"São causas de íleo paralítico, EXCETO:","options":{"A":"Infarto agudo do miocárdio.","B":"Infecções intra-abdominais.","C":"Procedimento cirúrgico longo.","D":"Pneumonia.","E":"Uso de narcóticos."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-127172","number":"127172","sourceNumber":"127172","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"A cicatrização de uma ferida cirúrgica é um processo biológico importante e pode ser\nafetado por vários fatores. Quanto ao\nprocesso de cicatrização, risco de deiscência de feridas\ncirúrgicas e infecção local, observe as afirmativas abaixo e responda qual afirmativa está ERRADA:","options":{"A":"Pacientes idosos apresentam maior risco de deiscência de ferida cirúrgica.","B":"Na primeira semana após o procedimento cirúrgico, ocorre a fase inflamatória do processo de\ncicatrização, caracterizado por dor, rubor, calor e edema.","C":"Cicatrização por segunda intenção está associada a ferimentos infectados, com grandes perdas\nteciduais.","D":"Antibióticos tópicos são excelentes para evitar infecções de feridas, principalmente nos\nferimentos extensos.","E":"Pacientes com insuficiências vasculares apresentam maior risco de deiscência de ferida\ncirúrgica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-102743","number":"102743","sourceNumber":"102743","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Aumentam os riscos da infecção do sítio cirúrgico, EXCETO:","options":{"A":"Uso crônico de corticoides.","B":"Idade avançada.","C":"Drenos posicionados por contra abertura e em sistema fechado.","D":"Obesidade."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-102746","number":"102746","sourceNumber":"102746","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em relação às fístulas anastomóticas, assinale a alternativa INCORRETA.","options":{"A":"A maioria não se fecha espontaneamente e necessita de reoperação.","B":"Fístula associada à peritonite requer cirurgia de urgência.","C":"Desnutrição, obstrução distal e infecção dificultam o fechamento espontâneo das fístulas.","D":"Cuidados com a pele, correção de distúrbios hidroeletrolíticos, hidratação venosa e jejum oral\nsão importantes no tratamento das fístulas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-106375","number":"106375","sourceNumber":"106375","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Todos os fatores abaixo estão relacionados a um maior risco de complicações\npulmonares no pós-operatório, exceto:","options":{"A":"idade acima dos 60 anos.","B":"asma com fluxo expiratório máximo de 220 L/min.","C":"doença pulmonar obstrutiva crônica.","D":"insuficiência cardíaca congestiva.","E":"volume expiratório forçado em 1 segundo de 1,5 L."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-100986","number":"100986","sourceNumber":"100986","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"T.V.Z., homem, 73 anos, necessita realizar tratamento cirúrgico de hérnia inguinal\nbilateral. Entretanto, devido sua idade, e ao fato\nde apresentar hipertensão arterial bem controlada\ncom uso de anlodipina, ele e sua família estão preocupados com os riscos da operação. Passou\nem avaliação com o cardiologista que o classificou como classe I de Goldman. Na consulta com o\nanestesiologista, foi classificado como classe II de ASA (American Society of Anesthesiologists).\n\nIsso significa que:","options":{"A":"O risco de morte de origem cardíaca para o doente em questão é aproximadamente 0,2%.","B":"Com oito pontos atribuídos pela idade, utilizando-se a classificação de Goldman, o doente\napresenta probabilidade de não complicação de 86%.","C":"O doente não está apto a ser operado, tendo em vista que, com a classificação ASA II tem alta\nprobabilidade de apresentar evento cardíaco no período intraoperatório.","D":"O doente está apto a ser operado, mas deve passar o período pós-operatório imediato em\nUnidade de Tratamento Intensivo.","E":"Os riscos potenciais à vida do doente em questão são de aproximadamente 11%."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-101019","number":"101019","sourceNumber":"101019","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"J.S.C., 28 anos, apresenta quadro clínico de colelitíase e é submetida à colecistectomia\nvideolaparoscópica. Durante o ato anestésico, apresenta taquicardia, labilidade pressórica,\nsudorese, rigidez de membros inferiores e hipertermia progressiva. O diagnóstico desta paciente foi\nde hipertermia maligna. Qual medicação deve ser administrada?","options":{"A":"Atropina.","B":"Dantrolene.","C":"Flumazenil.","D":"Naloxona.","E":"Biperideno."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-77350","number":"77350","sourceNumber":"77350","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"No seu primeiro dia de estágio no CTI Geral do Hospital Evangélico, seu preceptor\npede para que você inicie infusão de\nnoradrenalina na dose de 0,5 mcg/kg/min em um paciente de\n70 kg. Cada ampola de noradrenalina possui um total de 4 mg/4 ml (ou seja, 1 mg/ml). A solução\npadrão usada no CTI possui 5 ampolas que são adicionadas a 180 ml de soro fisiológico. Ao\nprogramar a bomba de infusão para atender essa necessidade, qual será a velocidade necessária\nem ml/h?","options":{"A":"21 ml/h.","B":"18,9 ml/h.","C":"2,1 ml/h.","D":"1,89 ml/h.","E":"18 ml/h."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-77338","number":"77338","sourceNumber":"77338","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Em um paciente em pós-operatório de gastrectomia total, você é orientado a garantir\num suporte calórico de 400 kcal em 24 horas,\npois o mesmo permanecerá em dieta zero. Dispondo,\npara isso, de ampolas de 10 ml de SG 50% (glicose anidra) para serem distribuídas na hidratação\ncom soro fisiológico que o paciente receberá. Quantas ampolas serão necessárias para atingir a\nmeta solicitada?","options":{"A":"20 ampolas.","B":"5 ampolas.","C":"15 ampolas.","D":"10 ampolas.","E":"50 ampolas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-77347","number":"77347","sourceNumber":"77347","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Num paciente em pós-operatório de gastrectomia total, você é orientado a garantir um\nsuporte calórico de 400 kcal em 24 horas, pois o mesmo permanecerá em dieta zero. Dispondo,\npara isso, de ampolas de 10 ml de SG 50% (glicose anidra) para serem distribuídas na hidratação\ncom soro fisiológico que o paciente receberá. No dia seguinte, você identifica nos exames um nível\nde potássio de 2,1 mg/dl, sintomático, e com alteração eletrocardiográfica. Neste caso:","options":{"A":"É necessária reposição rápida de potássio, com velocidade superior a 40 mEq/h.","B":"Caso a reposição seja feita em veia periférica, deve-se usar idealmente soluções com\nconcentração inferior a 40 mEq/L.","C":"O cálculo da reposição deverá ser feito de maneira muito precisa, utilizando-se das fórmulas\ndisponíveis, validadas e confiáveis.","D":"Em hipótese alguma repor magnésio junto, ou antes, da correção do potássio sob risco de\nagravamento da hipocalemia.","E":"Devido à alteração eletrocardiográfica identificada, deve-se administrar imediatamente gluconato\nde cálcio para estabilização da membrana\ncelular e prevenção de arritmias graves."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-09-77356","number":"77356","sourceNumber":"77356","collectionBlock":"med:med-cirurgia-med-cir-09","collectionLabel":"MED · MED CIR 09","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 09","subtopic":"","stem":"Sobre o suporte nutricional de pacientes clinicocirúrgicos, marque a alternativa\nCORRETA:","options":{"A":"Na pancreatite aguda grave, a nutrição parenteral total deve ser iniciada precocemente, se\npossível, no primeiro dia do diagnóstico.","B":"Pacientes submetidos à colectomia total ou parcial devem permanecer em jejum por pelo menos\n5 dias, uma vez que a alimentação aumenta o\nrisco de deiscência de anastomose.","C":"Pacientes criticamente enfermos que não conseguem atingir 60% do gasto energético total após\n5 dias de suporte enteral podem necessitar\nnutrição parenteral suplementar.","D":"Todas as formulações de nutrição parenteral existentes requerem infusão em acessos venosos\ncentrais.","E":"O suporte nutricional enteral em pacientes com pancreatite grave não deve ser iniciado antes de\n5 dias, devido ao risco de agravamento do\nquadro."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 09/MED CIR 09.txt","sourceLabel":"MED · MED CIR 09","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 09","MED"],"answerSource":"explicit","commentDeferred":true}]};
